const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'P(5,5)' },
      { kind: 'text', payload: '第一象限' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: '5' },
      { kind: 'text', payload: '5' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var r = function (v) { return Math.round(v * 100) / 100; };
    var tw = function (i) {
      var m = metrics && metrics[i];
      var w = m && (typeof m.width === 'number' ? m.width : m.w);
      return typeof w === 'number' ? w : 10;
    };

    var ox = Math.round(Math.min(78, W * 0.22));
    var oy = Math.round(H - Math.min(62, H * 0.24));
    var ux = (W - 46 - ox) / 6.2;
    var uy = (oy - 26) / 6.2;
    var u = Math.max(10, Math.min(ux, uy));
    var px = ox + 5 * u;
    var py = oy - 5 * u;

    var xAxis = ['M', r(ox), r(oy), 'L', r(W - 14), r(oy)];
    var xHead = visualSdk.arrow(r(W - 26), r(oy), r(W - 14), r(oy), {});
    var yAxis = ['M', r(ox), r(oy), 'L', r(ox), r(18)];
    var yHead = visualSdk.arrow(r(ox), r(30), r(ox), r(18), {});

    var tickCmds = [];
    for (var i = 1; i <= 5; i++) {
      var tx = ox + i * u;
      tickCmds.push('M', r(tx), r(oy - 4), 'L', r(tx), r(oy + 4));
      var ty = oy - i * u;
      tickCmds.push('M', r(ox - 4), r(ty), 'L', r(ox + 4), r(ty));
    }

    var dashed = function (x1, y1, x2, y2, d, g) {
      var dx = x2 - x1;
      var dy = y2 - y1;
      var len = Math.sqrt(dx * dx + dy * dy);
      if (len < 0.001) { return []; }
      var ux2 = dx / len;
      var uy2 = dy / len;
      var out = [];
      var t = 0;
      while (t < len) {
        var t2 = Math.min(t + d, len);
        out.push('M', r(x1 + ux2 * t), r(y1 + uy2 * t), 'L', r(x1 + ux2 * t2), r(y1 + uy2 * t2));
        t = t2 + g;
      }
      return out;
    };

    var vDash = dashed(px, py, px, oy, 6, 4);
    var hDash = dashed(px, py, ox, py, 6, 4);
    var dot = visualSdk.circle(r(px), r(py), 3.6);

    var qx = ox + 2.3 * u;
    var qy = oy - 4.2 * u;

    var labels = [
      { type: 'label', text: 'P(5,5)', x: r(px + 9), y: r(py - 11), fontSize: 13, fill: '#b03a2e', textAlign: 'left', textBaseline: 'middle' },
      { type: 'label', text: '第一象限', x: r(qx - tw(1) / 2), y: r(qy), fontSize: 13, fill: '#1f6f4a', textAlign: 'left', textBaseline: 'middle' },
      { type: 'label', text: 'x', x: r(W - 18), y: r(oy + 17), fontSize: 14, fill: '#26354a', textAlign: 'center', textBaseline: 'middle' },
      { type: 'label', text: 'y', x: r(ox + 16), y: r(20), fontSize: 14, fill: '#26354a', textAlign: 'center', textBaseline: 'middle' },
      { type: 'label', text: 'O', x: r(ox - 13), y: r(oy + 14), fontSize: 13, fill: '#26354a', textAlign: 'center', textBaseline: 'middle' },
      { type: 'label', text: '5', x: r(px - tw(5) / 2), y: r(oy + 17), fontSize: 12, fill: '#5b6b7d', textAlign: 'left', textBaseline: 'middle' },
      { type: 'label', text: '5', x: r(ox - 14 - tw(6)), y: r(py), fontSize: 12, fill: '#5b6b7d', textAlign: 'left', textBaseline: 'middle' }
    ];

    var children = [
      { type: 'path', pathId: 'xaxis', stroke: '#26354a', strokeWidth: 1.4, fill: 'none' },
      { type: 'path', pathId: 'xhead', stroke: '#26354a', strokeWidth: 1.4, fill: '#26354a' },
      { type: 'path', pathId: 'yaxis', stroke: '#26354a', strokeWidth: 1.4, fill: 'none' },
      { type: 'path', pathId: 'yhead', stroke: '#26354a', strokeWidth: 1.4, fill: '#26354a' },
      { type: 'path', pathId: 'ticks', stroke: '#26354a', strokeWidth: 1.2, fill: 'none' },
      { type: 'path', pathId: 'vdash', stroke: '#8a97a8', strokeWidth: 1.3, fill: 'none' },
      { type: 'path', pathId: 'hdash', stroke: '#8a97a8', strokeWidth: 1.3, fill: 'none' },
      { type: 'path', pathId: 'dot', stroke: '#b03a2e', strokeWidth: 1.4, fill: '#b03a2e' }
    ];
    for (var k = 0; k < labels.length; k++) { children.push(labels[k]); }

    return {
      schemaVersion: 1,
      sceneId: 'point-p-5-5',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'xaxis', commands: xAxis },
        { id: 'xhead', commands: xHead },
        { id: 'yaxis', commands: yAxis },
        { id: 'yhead', commands: yHead },
        { id: 'ticks', commands: tickCmds },
        { id: 'vdash', commands: vDash },
        { id: 'hdash', commands: hDash },
        { id: 'dot', commands: dot }
      ],
      root: { type: 'group', children: children }
    };
  }
};
